                  type="number"
                  dataKey="x"
                  name="Old-age dependency"
                  unit=""
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Old-age dependency (65+ / 15???64 ?? 100)",
                    position: "insideBottom",
                    offset: -16,
                    style: { fontSize: 11, fill: "#64748b" },
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Remit/GDP"
                  tick={{ fontSize: 11 }}
