                    position: "insideLeft",
                    style: { fontSize: 11, fill: "#64748b" },
                  }}
                />
                <ZAxis type="number" dataKey="z" range={[60, 400]} />
                <Tooltip content={<ScatterTooltip />} />
                <Scatter data={scatter} name="Countries">
                  {scatter.map((p) => (
                    <Cell key={p.id} fill={ROLE_COLORS[p.role]} fillOpacity={0.85} />
