                    />
                    <Line
                      type="monotone"
                      dataKey="italy"
                      name="Italy"
                      stroke={DEP_COLORS.italy}
                      strokeWidth={2}
                      dot={false}
                    />
                    <Line
                      type="monotone"
                      dataKey="germany"
                      name="Germany"
                      stroke={DEP_COLORS.germany}
                      strokeWidth={2}
                      dot={false}
                    />
                    <Line
                      type="monotone"
                      dataKey="unitedStates"
                      name="US"
                      stroke={DEP_COLORS.unitedStates}
                      strokeWidth={2}
                      dot={false}
                    />
                  </>
                )}
                {showOrigins && (
                  <>
                    <Line
                      type="monotone"
                      dataKey="mexico"
                      name="Mexico"
                      stroke={DEP_COLORS.mexico}
                      strokeWidth={2}
                      strokeDasharray="4 3"
                      dot={false}
                    />
                    <Line
                      type="monotone"
                      dataKey="india"
                      name="India"
                      stroke={DEP_COLORS.india}
                      strokeWidth={2}
                      strokeDasharray="4 3"
                      dot={false}
                    />
                    <Line
                      type="monotone"
                      dataKey="nigeria"
                      name="Nigeria"
                      stroke={DEP_COLORS.nigeria}
                      strokeWidth={2}
                      strokeDasharray="4 3"
                      dot={false}
                    />
