          }
          subtitle="Toggle metric: GDP-share vulnerability ??? dollar volume ??? host pension fiscal load."
        >
          <div className="h-[400px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
