      {panel === "corridors" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Top bilateral remittance corridors"
            subtitle="KNOMAD bilateral matrix ??? country-pair dollars, not recipient totals."
